window.decodeWf = function(s){
  const pts = s.trim().split('L').map(p=>p.trim().split(/\s+/).map(Number));
  const top=[]; let lastX=-1;
  for(const [x,y] of pts){ if(x<lastX) break; top.push([x,y]); lastX=x; }
  const N = top[top.length-1][0]; const amp=[]; let j=0;
  for(let x=0;x<=N;x++){ while(j<top.length-2 && top[j+1][0]<x) j++; const [x0,y0]=top[j], [x1,y1]=top[Math.min(j+1,top.length-1)]; const y = x1===x0? y0 : y0+(y1-y0)*(x-x0)/(x1-x0); amp.push(15-y); }
  return {N, amp};
};
window.envStr = function(wf, dur, win){ const {N,amp}=window.decodeWf(wf); const per=N/dur; const out=[]; for(let t=0;t<dur;t+=win){ const a=Math.floor(t*per), b=Math.min(amp.length,Math.floor((t+win)*per)+1); let s=0,c=0; for(let i=a;i<b;i++){s+=amp[i];c++;} out.push(c?(s/c):0);} return out; };
window.inspectId = async function(id){
  const resp = await fetch('/music/x-'+id+'/'); const href=new URL(resp.url).pathname; const html=await resp.text();
  const m = html.match(/__BOOTSTRAP_URL__\s*=\s*["']([^"']+)["']/); if(!m) return {id,err:'nobs',href};
  const j = await (await fetch(m[1])).json(); const mi=(j.page||j).mediaItem; if(!mi) return {id,err:'nomi',href};
  let env=null; try{ const wfs=await (await fetch('/music/'+id+'/waveform.json')).json(); env=window.envStr(wfs,mi.duration,5).map(v=>Math.round(v).toString(16)).join(''); }catch(e){}
  return {id,n:mi.name,u:mi.user.username,d:Math.round(mi.duration),ai:mi.isAiGenerated?1:0,cid:mi.hasYoutubeContentId?1:0,lq:mi.isLowQuality?1:0,ec:mi.isEditorsChoice?1:0,g:(mi.genres||[]).join('/'),m:(mi.moods||[]).join('/'),mv:(mi.movements||[]).join('/'),desc:mi.description,tags:(mi.tags||[]).slice(0,10).join(','),dl:mi.downloadCount,href:mi.href,env};
};
